#!/usr/bin/env python3
"""Build the static Houston site from reviewed content. Standard library only."""
from pathlib import Path
import json,html,re
ROOT=Path(__file__).resolve().parents[1]
BASE='https://houstondumpsterrentalco.shop'
PHONE='+13466602743'
DATA=json.loads((ROOT/'content.json').read_text())
SERVICES=[d for d in DATA if d['kind']=='service']
AREAS=[d for d in DATA if d['kind']=='area']
def esc(s):return html.escape(s,quote=True)
def href(d):return '/'+d['slug']+'/'
def link(d):return f'<a href="{href(d)}">{esc(d["label"])}</a>'
def call(label='Call (346) 660-2743',cls='button'):return f'<a class="{cls}" href="tel:{PHONE}">{label}</a>'
def header(home=False):
 return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="/" aria-label="Houston Dumpster Rental home"><img src="/assets/logo.svg" width="46" height="46" alt=""><span>Houston<span>Dumpster Rental</span></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav">Menu</button><nav id="site-nav" aria-label="Main navigation"><details class="nav-dropdown"><summary>Services</summary><div>{''.join(link(d) for d in SERVICES)}<a href="/services/">All services</a></div></details><details class="nav-dropdown"><summary>Areas</summary><div>{''.join(link(d) for d in AREAS)}<a href="/areas/">All areas</a></div></details><a href="/dumpster-sizes/">Size guide</a><a href="/#questions">FAQs</a></nav>{call(cls='button small header-call')}</header>'''
def footer():
 return f'''<footer class="site-footer"><div class="footer-top"><a class="brand" href="/"><img src="/assets/logo.svg" width="46" height="46" alt=""><span>Houston<span>Dumpster Rental</span></span></a><address>2812 Center St<br>Houston, TX 77007</address>{call()}</div><div class="footer-columns"><div><h2>Services</h2>{''.join(link(d) for d in SERVICES)}</div><div><h2>Houston area</h2>{''.join(link(d) for d in AREAS)}</div><div><h2>Plan your project</h2><a href="/dumpster-sizes/">Dumpster size guide</a><a href="/#plan">Rental checklist</a><a href="/#questions">Rental questions</a><a href="/site-map/">Site map</a></div></div><div class="footer-bottom"><small>© 2026 Houston Dumpster Rental</small><p>Confirm container availability, accepted materials and delivery for your address.</p></div></footer><div class="mobile-call">{call('Call about your rental')}<a href="/areas/">Find your area</a></div>'''
def schema(slug,title,desc,kind='guide'):
 url=BASE+'/'+(slug+'/' if slug else '')
 business={'@type':['LocalBusiness','Organization'],'@id':BASE+'/#business','name':'Houston Dumpster Rental','url':BASE+'/','telephone':PHONE,'logo':{'@type':'ImageObject','url':BASE+'/assets/logo.svg'},'image':BASE+'/assets/hero-poster.jpg','address':{'@type':'PostalAddress','streetAddress':'2812 Center St','addressLocality':'Houston','addressRegion':'TX','postalCode':'77007','addressCountry':'US'},'geo':{'@type':'GeoCoordinates','latitude':29.76948834818,'longitude':-95.38765257458}}
 site={'@type':'WebSite','@id':BASE+'/#website','url':BASE+'/','name':'Houston Dumpster Rental','publisher':{'@id':BASE+'/#business'},'inLanguage':'en-US'}
 webpage={'@type':'CollectionPage' if kind=='hub' else 'WebPage','@id':url+'#webpage','url':url,'name':title,'description':desc,'isPartOf':{'@id':BASE+'/#website'},'about':{'@id':BASE+'/#business'},'inLanguage':'en-US'}
 graph=[business,site,webpage]
 if slug:
  items=[{'@type':'ListItem','position':1,'name':'Home','item':BASE+'/'}]
  if slug.startswith('areas/'):
   items.append({'@type':'ListItem','position':2,'name':'Areas','item':BASE+'/areas/'})
  items.append({'@type':'ListItem','position':len(items)+1,'name':title,'item':url})
  graph.append({'@type':'BreadcrumbList','@id':url+'#breadcrumb','itemListElement':items});webpage['breadcrumb']={'@id':url+'#breadcrumb'}
 if kind=='service' or not slug:
  graph.append({'@type':'Service','@id':url+'#service','name':title,'serviceType':'Dumpster rental','provider':{'@id':BASE+'/#business'},'areaServed':{'@type':'City','name':'Houston'},'url':url,'description':desc});webpage['mainEntity']={'@id':url+'#service'}
 return '<script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False)+'</script>'
def page(slug,title,desc,body,kind='guide',home=False):
 url=BASE+'/'+(slug+'/' if slug else '')
 preload='<link rel="preload" as="image" href="/assets/hero-poster.jpg" fetchpriority="high">' if home else ''
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{url}"><meta name="theme-color" content="#102847"><link rel="icon" href="/assets/logo.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css">{preload}<meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><meta property="og:image" content="{BASE}/assets/hero-poster.jpg"><meta property="og:locale" content="en_US">{schema(slug,title,desc,kind)}<script src="/site.js" defer></script></head><body class="{'home-page' if home else 'inner-page'}">{header(home)}<main id="main">{body}</main>{footer()}</body></html>'''
def write(slug,text):
 path=ROOT/slug/'index.html' if slug else ROOT/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text)
def cards(items):
 return '<div class="directory-grid">'+''.join(f'<a class="directory-card" href="{href(d)}"><h3>{esc(d["label"])}</h3><p>{esc(d["description"])}</p><span>Explore {"area" if d["kind"]=="area" else "service"} <span aria-hidden="true">↗</span></span></a>' for d in items)+'</div>'
for d in DATA:
 crumbs='<a href="/">Home</a> / '+('<a href="/areas/">Areas</a> / ' if d['kind']=='area' else '')+esc(d['label'])
 source=f'<p class="local-source">Local reference: <a href="{esc(d["source"])}" target="_blank" rel="noopener">Community and property information for {esc(d["label"])}</a>. Confirm current requirements for your address.</p>' if d.get('source') else ''
 related=[x for x in SERVICES if x['slug']!=d['slug']]
 body=f'''<section class="guide-hero"><nav class="breadcrumbs" aria-label="Breadcrumb">{crumbs}</nav><h1>{esc(d['h1'])}</h1><p>{esc(d['description'])}</p>{call('Call to discuss your project')}</section><div class="guide-layout"><article class="guide-content">{d['body']}{source}<section class="article-call"><h2>Let’s talk about your project.</h2><p>Call with your address, debris type and preferred dates. We’ll discuss the rental options and details for your location.</p>{call()}</section></article><aside class="guide-aside"><img src="/assets/container.svg" alt="Illustrated blue roll-off dumpster" width="1000" height="640" loading="lazy"><h2>Room for your next project.</h2><p>Discuss materials, placement and timing before you rent.</p>{call('Call about availability')}<div class="related"><h3>Explore services</h3>{''.join(link(x) for x in related)}<a href="/dumpster-sizes/">Dumpster size guide</a><a href="/areas/">Houston area guides</a></div></aside></div>'''
 write(d['slug'],page(d['slug'],d['title'],d['description'],body,d['kind']))
hero=f'''<section class="video-hero" aria-label="Houston dumpster rental"><video class="hero-video" id="hero-video" muted loop playsinline preload="none" poster="/assets/hero-poster.jpg" aria-hidden="true" tabindex="-1"><source data-src="/assets/hero-dumpster.mp4" type="video/mp4"></video><div class="hero-shade"></div><div class="video-hero-content"><p class="hero-location">Houston &amp; surrounding communities</p><h1>Big project.<br>We make room.</h1><p class="hero-intro">Dumpster rentals for home cleanouts, renovations and the work ahead. Tell us what’s going. Let’s plan the right fit.</p><div class="hero-actions">{call()}<a class="button ghost" href="/services/">Explore services</a></div></div><div class="hero-bottom"><span>Home cleanouts <b> / </b> Construction <b> / </b> Roofing</span><button id="video-toggle" class="video-toggle" type="button" aria-controls="hero-video" aria-label="Play background video" hidden>Play video</button></div></section>'''
rest=(ROOT/'templates/home-content.html').read_text()
rest=re.sub(r'<a class="button(?: yellow)?" href="#plan">.*?</a>',call(),rest)
rest=rest.replace('<p>You don’t need to know every detail yet.<br>Start with these three.</p>','<p>You don’t need to know every detail yet.<br>Start with these three, then call us.</p>')
rest=rest.replace('Make space for what comes next.','Make space for what comes next.')
rest=rest.replace('<details><summary>Can I arrange a specific delivery date?</summary>','<details><summary>How do I get started?</summary><p>Call (346) 660-2743 with your project address, debris type and preferred dates. We’ll discuss container options, accepted materials, placement and the full rental details.</p></details><details><summary>Can I arrange a specific delivery date?</summary>')
extra='<section class="section"><div class="section-head"><h2>A rental for<br>the job you’re doing.</h2><p>Explore the details for your project, from a household cleanout to a roofing tear-off.</p></div>'+cards(SERVICES)+'</section><section class="section area-feature"><div class="section-head"><h2>Houston is home.<br>Find your area.</h2><p>Explore local planning guides, then call to confirm delivery options for your address.</p></div><div class="area-link-grid">'+''.join(link(d) for d in AREAS)+'</div></section>'
rest=rest.replace('<section id="process"',extra+'<section id="process"')
write('',page('','Houston Dumpster Rental | Home & Construction Projects','Houston dumpster rentals for cleanouts, roofing and construction projects. Call (346) 660-2743 to discuss materials, container options and delivery.',hero+rest,'service',True))
hubs=[('services','Dumpster Rental Services in Houston','Dumpster Rental Services Houston | Explore Your Project','Explore Houston dumpster rental services for residential cleanouts, construction, roofing and commercial projects. Call to plan your rental.',SERVICES,'Different projects.\nOne clear plan.'),('areas','Houston Neighborhoods & Surrounding Areas','Houston Dumpster Rental Areas | Neighborhoods & Cities','Explore dumpster rental planning guides for Katy, Cypress, Spring, The Woodlands, Sugar Land, Pearland, The Heights and Montrose. Call to check delivery.',AREAS,'Your project.\nYour neighborhood.')]
for slug,h1,title,desc,items,thesis in hubs:
 intro='Find the guide for your project. Each service page covers materials, placement, weight and scheduling questions to settle before you rent.' if slug=='services' else 'From Inner Loop neighborhoods to surrounding communities, every property needs its own plan. These guides cover local considerations; call to confirm available delivery arrangements for your exact address.'
 body=f'<section class="guide-hero"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a> / {esc(slug.title())}</nav><h1>{esc(h1)}</h1><p>{esc(intro)}</p>{call()}</section><section class="section hub-content">{cards(items)}<div class="hub-note"><h2>{esc(thesis).replace(chr(10),"<br>")}</h2><p>Start with the debris, the proposed placement and your preferred dates. Container specifications, accepted materials, weight terms and delivery availability are confirmed for the actual rental.</p><p>Our Houston business address is 2812 Center St, Houston, TX 77007. The area guides do not represent separate branches or offices.</p><a class="text-link" href="/dumpster-sizes/">Read the dumpster size guide</a></div></section>'
 write(slug,page(slug,title,desc,body,'hub'))
all_pages=[{'slug':'','label':'Home','description':'Houston dumpster rental overview and project planning.'}]+DATA+[{'slug':slug,'label':h1,'description':desc} for slug,h1,title,desc,*_ in hubs]+[{'slug':'site-map','label':'Site map','description':'All pages on this website.'}]
mapbody='<section class="guide-hero"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a> / Site map</nav><h1>Good information.<br>All in one place.</h1><p>Explore our services, project guides and Houston area pages.</p></section><section class="section sitemap-directory"><h2>Services</h2>'+cards(SERVICES)+'<h2>Houston area guides</h2>'+cards(AREAS)+'<h2>More information</h2><div class="area-link-grid"><a href="/">Home</a><a href="/services/">All services</a><a href="/areas/">All areas</a><a href="/dumpster-sizes/">Dumpster size guide</a><a href="/sitemap.xml">XML sitemap</a></div></section>'
write('site-map',page('site-map','Site Map | Houston Dumpster Rental','Find every Houston Dumpster Rental service, local area guide and planning resource. Explore residential, roofing, construction and commercial rentals.',mapbody,'hub'))
xml='<?xml version="1.0" encoding="UTF-8"?>\n<?xml-stylesheet type="text/css" href="/sitemap.css"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url>\n    <loc>{BASE}/{d["slug"]+("/" if d["slug"] else "")}</loc>\n    <lastmod>2026-10-25</lastmod>\n  </url>\n' for d in all_pages)+'</urlset>\n'
for name in ['sitemap.xml','sitemaps.xml']:(ROOT/name).write_text(xml)
css=(ROOT/'sitemap.css').read_text();css=re.sub(r'\d+ canonical pages',f'{len(all_pages)} canonical pages',css);(ROOT/'sitemap.css').write_text(css)
(ROOT/'STRUCTURE.md').write_text('# Houston website structure\n\nRebuild with `python3 scripts/build_site.py`. Reviewed source: `content.json` and `templates/home-content.html`. No frontend dependencies.\n\n'+f'{len(all_pages)} canonical HTML pages; five services and eight owner-approved area guides. Both styled XML sitemaps contain the complete set.\n\n'+'\n'.join(f'- `/{d["slug"]+("/" if d["slug"] else "")}` — {d["label"]}' for d in all_pages)+'\n\nOne Houston LocalBusiness entity, confirmed phone/address and Census-matched coordinates. Area pages are WebPages, not invented branch entities. No reviews, prices, hours or inventory claims. Licensed locally hosted hero footage; see SOURCES.txt.\n')
print('Built',len(all_pages),'pages:',len(SERVICES),'services;',len(AREAS),'area guides')
